def count_Primes_nums(n: int) -> int:
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    limit = int(n ** 0.5) + 1
    for i in range(2, limit):
        if sieve[i]:
            step = i
            start = i * i
            sieve[start:n:step] = [False] * ((n - start - 1) // step + 1)
    return sum(sieve)
```

