def maxAverageOfPath(matrix):
    n = len(matrix)
    if n == 0:
        return 0.0
    min_val = min(min(row) for row in matrix)
    max_val = max(max(row) for row in matrix)

    def feasible(avg):
        dp_prev = [0.0] * n
        for i in range(n):
            dp_curr = [0.0] * n
            for j in range(n):
                w = matrix[i][j] - avg
                if i == 0 and j == 0:
                    val = w
                else:
                    up = dp_prev[j] if i > 0 else -float('inf')
                    left = dp_curr[j - 1] if j > 0 else -float('inf')
                    val = w + (up if up > left else left)
                dp_curr[j] = val
            dp_prev = dp_curr
        return dp_prev[-1] >= 0

    low, high = min_val, max_val
    for _ in range(60):
        mid = (low + high) / 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    return round(low, 6)
